// Safe score extractor: returns { obtained, max, percentage } or null if invalid/NaN
function extractValidScore(s) {
  if (window.api && typeof window.api.extractValidScore === "function") {
    return window.api.extractValidScore(s);
  }
  if (!s || typeof s !== "object") return null;
  let obtained = null;
  let max = null;
  if (s.score_obtained !== undefined && s.score_obtained !== null && s.score_obtained !== "") {
    const parsed = parseFloat(s.score_obtained);
    if (!isNaN(parsed) && isFinite(parsed)) obtained = parsed;
  }
  if (s.max_score !== undefined && s.max_score !== null && s.max_score !== "") {
    const parsedMax = parseFloat(s.max_score);
    if (isNaN(parsedMax) || !isFinite(parsedMax) || parsedMax <= 0) {
      return null;
    }
    max = parsedMax;
  }
  if (obtained === null) {
    if (s.total_score !== undefined && s.total_score !== null && s.total_score !== "") {
      const parsedTotal = parseFloat(s.total_score);
      if (!isNaN(parsedTotal) && isFinite(parsedTotal)) {
        obtained = parsedTotal;
        if (max === null) max = 100;
      }
    } else if (s.class_score !== undefined || s.ca_score !== undefined || s.exam_score !== undefined) {
      const cls = parseFloat(s.class_score || s.ca_score || 0);
      const exm = parseFloat(s.exam_score || 0);
      if (!isNaN(cls) && !isNaN(exm)) {
        obtained = cls + exm;
        if (max === null) max = 100;
      }
    }
  }
  if (obtained === null || isNaN(obtained) || !isFinite(obtained)) return null;
  if (max === null) max = 100;
  if (isNaN(max) || !isFinite(max) || max <= 0) return null;
  const pct = (obtained / max) * 100;
  if (isNaN(pct) || !isFinite(pct) || pct < 0) return null;
  return { obtained, max, percentage: pct };
}

// Safe percentage parser: parses "85%", 85, etc. and returns null if NaN, N/A, or invalid
function parseValidPercentage(val) {
  if (window.api && typeof window.api.parseValidPercentage === "function") {
    return window.api.parseValidPercentage(val);
  }
  if (val === null || val === undefined || val === "" || val === "N/A" || val === "NaN" || val === "undefined") {
    return null;
  }
  const clean = String(val).replace(/%/g, "").trim();
  const num = parseFloat(clean);
  if (isNaN(num) || !isFinite(num)) return null;
  return num;
}

// Generalized Offline Sync for all stores
async function syncDirtyRecords() {
  if (!window.db) return;
  try {
    const stores = [
      "users", "profiles", "classes", "enrolments", "class_posts", 
      "financial_transactions", "audit_logs", "attendance", "assignments", 
      "student_scores", "lesson_notes", "pickup_guardians", "cms_content", 
      "staff_tasks", "notifications", "sectional_reports", "questionnaires", 
      "questionnaire_responses", "bank_reconciliations", "prospectuses", 
      "broadcast_requests", "data_change_requests", "academic_calendar",
      "elibrary_books", "parent_profiles", "parent_student_relations",
      "notification_user_reads", "portal_messages", "broadcast_archives",
      "custom_recipient_groups", "subjects"
    ];
    
    let totalSynced = 0;
    
    for (const storeName of stores) {
      const records = await window.db.getAll(storeName);
      const unsynced = records.filter(r => r.synced === false);
      
      if (unsynced.length > 0) {
        for (const item of unsynced) {
          item.synced = true;
          await window.db.putLocal(storeName, item);
          
          // Upload to Firebase if configured
          if (window.isFirebaseConfigured && window.isFirebaseConfigured()) {
            try {
              const docId = window.db.getDocId(storeName, item);
              if (docId) {
                await firebase.firestore().collection(storeName).doc(docId).set(item);
              }
            } catch (fbErr) {
              console.warn(`Sync failed for ${storeName} key:`, item, fbErr);
              // Revert to unsynced so it retries later
              item.synced = false;
              await window.db.putLocal(storeName, item);
            }
          }
        }
        if (typeof window.bumpCloudStoreVersion === "function") {
          window.bumpCloudStoreVersion(storeName).catch(() => {});
        }
        totalSynced += unsynced.length;
      }
    }
    
    if (totalSynced > 0) {
      showToast(`Automatically synchronized ${totalSynced} pending offline database records!`, "success");
    }
  } catch (err) {
    console.error("Generalized offline sync error:", err);
  }
}
window.syncDirtyRecords = syncDirtyRecords;

// ==========================================
// 2. TOAST NOTIFICATION WIDGET             
// ==========================================
function showToast(message, type = "info") {
  const container = document.getElementById("toast-container");
  if (!container) return;

  const toast = document.createElement("div");
  toast.className = `toast toast-${type}`;
  
  let icon = "ℹ️";
  if (type === "success") icon = "✅";
  if (type === "warning") icon = "⚠️";
  if (type === "danger") icon = "🚨";

  toast.innerHTML = `
    <div style="display:flex; align-items:center; gap:0.5rem;">
      <span>${icon}</span>
      <span>${message}</span>
    </div>
    <button style="cursor:pointer; color:var(--text-secondary); opacity:0.7; font-size:1.1rem;" onclick="this.parentElement.remove()">✕</button>
  `;

  container.appendChild(toast);
  
  setTimeout(() => {
    toast.remove();
  }, 4500);
}

window.showToast = showToast;

// ==========================================
// 3. THEME MANAGER                          
// ==========================================
function initTheme() {
  const savedTheme = localStorage.getItem("theme") || "light";
  if (savedTheme === "light") {
    document.body.classList.add("light-theme");
  } else {
    document.body.classList.remove("light-theme");
  }
}

function toggleTheme() {
  if (document.body.classList.contains("light-theme")) {
    document.body.classList.remove("light-theme");
    localStorage.setItem("theme", "dark");
    showToast("Switched to Premium Dark Mode", "success");
  } else {
    document.body.classList.add("light-theme");
    localStorage.setItem("theme", "light");
    showToast("Switched to Light Mode", "success");
  }
}

// ==========================================
// 4. ROUTER SYSTEM (SPA NAVIGATION)         
// ==========================================
function navigateTo(viewId) {
  const landing = document.getElementById("view-landing");
  if (landing) landing.classList.add("portal-hidden");
  
  const login = document.getElementById("view-login");
  if (login) login.classList.add("portal-hidden");
  
  const shell = document.getElementById("view-dashboard-shell");
  if (shell) shell.classList.add("portal-hidden");
  
  const setpwd = document.getElementById("view-set-password");
  if (setpwd) setpwd.classList.add("portal-hidden");

  const targetView = document.getElementById(viewId);
  if (targetView) {
    targetView.classList.remove("portal-hidden");
    window.scrollTo(0, 0);
  }
}

