// 9. APP INITIALIZATION & ROUTING
// ==========================================
// ==========================================
// UNIVERSAL DESKTOP HORIZONTAL TABLE SCROLL NAV BUTTONS
// ==========================================
function initTableScrollEnhancements() {
  const tableContainers = document.querySelectorAll(".table-container");

  tableContainers.forEach((container) => {
    let wrapper = container.parentElement;
    if (!wrapper || !wrapper.classList.contains("table-scroll-wrapper")) {
      wrapper = document.createElement("div");
      wrapper.className = "table-scroll-wrapper";
      container.parentNode.insertBefore(wrapper, container);
      wrapper.appendChild(container);

      // Create Slim Left Scroll Button
      const btnLeft = document.createElement("button");
      btnLeft.type = "button";
      btnLeft.className = "table-scroll-nav-btn table-scroll-nav-left";
      btnLeft.setAttribute("aria-label", "Scroll table left");
      btnLeft.setAttribute("title", "Scroll left (click or hold)");
      btnLeft.innerHTML = `
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="15 18 9 12 15 6"></polyline>
        </svg>
      `;

      // Create Slim Right Scroll Button
      const btnRight = document.createElement("button");
      btnRight.type = "button";
      btnRight.className = "table-scroll-nav-btn table-scroll-nav-right";
      btnRight.setAttribute("aria-label", "Scroll table right");
      btnRight.setAttribute("title", "Scroll right (click or hold)");
      btnRight.innerHTML = `
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="9 18 15 12 9 6"></polyline>
        </svg>
      `;

      wrapper.appendChild(btnLeft);
      wrapper.appendChild(btnRight);

      // Press and hold continuous scroll or click smooth scroll
      const attachScrollHandlers = (btn, direction) => {
        let holdTimer = null;
        let animId = null;
        let startTime = 0;
        let isHolding = false;

        const stop = () => {
          if (holdTimer) {
            clearTimeout(holdTimer);
            holdTimer = null;
          }
          if (animId) {
            cancelAnimationFrame(animId);
            animId = null;
          }
          window.removeEventListener("mouseup", stop);
          window.removeEventListener("touchend", stop);
          window.removeEventListener("touchcancel", stop);
        };

        const start = (e) => {
          if (e.button !== undefined && e.button !== 0) return; // Only primary mouse button
          isHolding = false;
          startTime = Date.now();

          // Wait 200ms before initiating continuous smooth scrolling
          holdTimer = setTimeout(() => {
            isHolding = true;
            let step = 10;
            const continuousScroll = () => {
              container.scrollLeft += direction * step;
              step = Math.min(step + 0.5, 26);
              animId = requestAnimationFrame(continuousScroll);
            };
            animId = requestAnimationFrame(continuousScroll);
          }, 200);

          window.addEventListener("mouseup", stop);
          window.addEventListener("touchend", stop);
          window.addEventListener("touchcancel", stop);
        };

        btn.addEventListener("mousedown", start);
        btn.addEventListener("touchstart", start, { passive: true });

        btn.addEventListener("click", (e) => {
          e.preventDefault();
          e.stopPropagation();
          // If release was quick, perform smooth horizontal scroll step
          if (!isHolding && (Date.now() - startTime) < 220) {
            const scrollDistance = Math.max(260, Math.floor(container.clientWidth * 0.5));
            container.scrollBy({ left: direction * scrollDistance, behavior: "smooth" });
          }
        });
      };

      attachScrollHandlers(btnLeft, -1);
      attachScrollHandlers(btnRight, 1);

      // Dynamic button state and vertical viewport centering updater
      const updateButtons = () => {
        const maxScroll = container.scrollWidth - container.clientWidth;
        const hasOverflow = maxScroll > 4;

        if (!hasOverflow) {
          btnLeft.classList.remove("is-visible");
          btnRight.classList.remove("is-visible");
          return;
        }

        if (container.scrollLeft > 4) {
          btnLeft.classList.add("is-visible");
        } else {
          btnLeft.classList.remove("is-visible");
        }

        if (container.scrollLeft < maxScroll - 4) {
          btnRight.classList.add("is-visible");
        } else {
          btnRight.classList.remove("is-visible");
        }

        // Keep buttons centered vertically in user's viewport within the table height
        const rect = container.getBoundingClientRect();
        const headerHeight = 65;
        const visibleTop = Math.max(rect.top, headerHeight);
        const visibleBottom = Math.min(rect.bottom, window.innerHeight);

        if (visibleBottom > visibleTop) {
          const centerScreenY = (visibleTop + visibleBottom) / 2;
          const offsetInContainer = centerScreenY - rect.top;
          const btnHalfH = 34;
          const clampedY = Math.max(btnHalfH + 6, Math.min(rect.height - btnHalfH - 6, offsetInContainer));
          btnLeft.style.top = `${clampedY}px`;
          btnRight.style.top = `${clampedY}px`;
        }
      };

      container._updateTableScrollNav = updateButtons;
      container.addEventListener("scroll", updateButtons, { passive: true });

      if (window.ResizeObserver) {
        const ro = new ResizeObserver(() => updateButtons());
        ro.observe(container);
        if (container.firstElementChild) {
          ro.observe(container.firstElementChild);
        }
      }

      updateButtons();
      setTimeout(updateButtons, 150);
      setTimeout(updateButtons, 600);
    } else {
      if (typeof container._updateTableScrollNav === "function") {
        container._updateTableScrollNav();
      }
    }
  });
}

window.initTableScrollEnhancements = initTableScrollEnhancements;

let tableScrollTicking = false;
function updateAllTableScrollNavs() {
  const containers = document.querySelectorAll(".table-container");
  containers.forEach(c => {
    if (typeof c._updateTableScrollNav === "function") {
      c._updateTableScrollNav();
    }
  });
}

window.addEventListener("scroll", () => {
  if (!tableScrollTicking) {
    requestAnimationFrame(() => {
      updateAllTableScrollNavs();
      tableScrollTicking = false;
    });
    tableScrollTicking = true;
  }
}, { passive: true });

window.addEventListener("resize", () => {
  if (!tableScrollTicking) {
    requestAnimationFrame(() => {
      updateAllTableScrollNavs();
      tableScrollTicking = false;
    });
    tableScrollTicking = true;
  }
}, { passive: true });

document.addEventListener("DOMContentLoaded", async () => {
  initTheme();
  await initAcademicCalendarCache();
  await initDailyBirthdayAutoScheduler();
  
  initTableScrollEnhancements();

  // Automatic observer for dynamically rendered subviews, tabs, and tables
  const tableMutationObserver = new MutationObserver(() => {
    initTableScrollEnhancements();
  });
  const subviewRoot = document.getElementById("dashboard-subview-container") || document.body;
  tableMutationObserver.observe(subviewRoot, { childList: true, subtree: true });

  document.getElementById("btn-theme-toggle-portal").addEventListener("click", toggleTheme);

  document.getElementById("btn-back-to-site").addEventListener("click", () => {
    window.location.href = "../website/index.html";
  });

  const drawerBtn = document.getElementById("btn-sidebar-toggle");
  const sidebarDrawer = document.getElementById("sidebar-drawer");
  const sidebarBackdrop = document.getElementById("sidebar-backdrop");
  const sidebarCloseBtn = document.getElementById("btn-sidebar-close");

  window.closePortalSidebarDrawer = () => {
    if (sidebarDrawer) {
      sidebarDrawer.classList.remove("mobile-open");
    }
    if (sidebarBackdrop) {
      sidebarBackdrop.classList.remove("active");
    }
    document.body.style.overflow = "";
  };

  window.openPortalSidebarDrawer = () => {
    if (sidebarDrawer) {
      sidebarDrawer.classList.add("mobile-open");
    }
    if (sidebarBackdrop) {
      sidebarBackdrop.classList.add("active");
    }
    document.body.style.overflow = "hidden";
  };

  if (drawerBtn && sidebarDrawer) {
    drawerBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (sidebarDrawer.classList.contains("mobile-open")) {
        window.closePortalSidebarDrawer();
      } else {
        window.openPortalSidebarDrawer();
      }
    });

    if (sidebarBackdrop) {
      sidebarBackdrop.addEventListener("click", (e) => {
        e.stopPropagation();
        window.closePortalSidebarDrawer();
      });
    }

    if (sidebarCloseBtn) {
      sidebarCloseBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        window.closePortalSidebarDrawer();
      });
    }

    document.addEventListener("click", (e) => {
      if (sidebarDrawer.classList.contains("mobile-open")) {
        if (!sidebarDrawer.contains(e.target) && !drawerBtn.contains(e.target)) {
          window.closePortalSidebarDrawer();
        }
      }
    });
  }

  // Universal Password Visibility Toggle Hook
  document.querySelectorAll(".btn-toggle-password").forEach(btn => {
    btn.addEventListener("click", () => {
      const targetId = btn.getAttribute("data-target");
      const targetInput = document.getElementById(targetId);
      if (!targetInput) return;

      const isPassword = targetInput.type === "password";
      targetInput.type = isPassword ? "text" : "password";

      if (isPassword) {
        btn.innerHTML = `
          <svg class="eye-icon" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color:var(--accent-primary);">
            <path d="M9.88 9.88a3 3 0 1 0 4.24 4.24"/>
            <path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"/>
            <path d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"/>
            <line x1="2" x2="22" y1="2" y2="22"/>
          </svg>
        `;
        btn.setAttribute("title", "Hide Password");
      } else {
        btn.innerHTML = `
          <svg class="eye-icon" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/>
            <circle cx="12" cy="12" r="3"/>
          </svg>
        `;
        btn.setAttribute("title", "Show Password");
      }
    });
  });

  document.getElementById("form-portal-login").addEventListener("submit", handlePortalLogin);
  document.getElementById("form-forced-reset").addEventListener("submit", handleForcedReset);

  document.getElementById("btn-notifications-toggle").addEventListener("click", () => {
    const sidebar = document.getElementById("sidebar-menu-links");
    if (sidebar) {
      const links = sidebar.querySelectorAll(".sidebar-link");
      links.forEach(l => l.classList.remove("active"));
    }
    loadDashboardSubview("notifications-portal");
  });

    document.getElementById("btn-logout").addEventListener("click", async () => {
    // 1. Sign out of Firebase Auth if active
    if (window.firebase && window.firebase.auth) {
      try {
        await firebase.auth().signOut();
      } catch (authErr) {
        console.warn("Firebase signOut notice:", authErr);
      }
    }

    // 2. Clear in-memory session
    const prevUserId = currentUser ? currentUser.user_id : null;
    currentUser = null;
    currentToken = null;
    if (window.api) {
      window.api.currentUser = null;
    }

    // 3. Purge session tokens and sync watermarks from localStorage
    localStorage.removeItem("fja_session_token");
    localStorage.removeItem("fja_session_user");
    if (prevUserId) {
      localStorage.removeItem(`fja_last_view_${prevUserId}`);
    }
    Object.keys(localStorage).forEach(key => {
      if (key.startsWith("fja_last_sync_") || key.startsWith("fja_last_view_")) {
        localStorage.removeItem(key);
      }
    });

    // 4. Safely close active IndexedDB connection so database doesn't lock
    if (window.db && typeof window.db.close === "function") {
      try { window.db.close(); } catch(e) {}
    }
    if (typeof window.clearAllFirestoreListeners === "function") {
      try { window.clearAllFirestoreListeners(); } catch(e) {}
    }

    // 5. Cleanly reload to view-login to reinitialize clean state without blocking
    window.location.href = window.location.pathname;
  });

  const profPhotoInput = document.getElementById("prof-photo-file-input");
  if (profPhotoInput) {
    profPhotoInput.addEventListener("change", async (e) => {
      const file = e.target.files[0];
      if (file) {
        try {
          const base64Url = await compressImage(file, 320, 320, 0.82);
          document.getElementById("prof-photo-url-val").value = base64Url;
          document.getElementById("profile-modal-img").src = base64Url;
        } catch (err) {
          console.warn("Profile image compression fallback:", err);
          const reader = new FileReader();
          reader.onload = (event) => {
            const base64Url = event.target.result;
            document.getElementById("prof-photo-url-val").value = base64Url;
            document.getElementById("profile-modal-img").src = base64Url;
          };
          reader.readAsDataURL(file);
        }
      }
    });
  }

  // --- Password Initialization link validation routing ---
  const urlParams = new URLSearchParams(window.location.search);
  const action = urlParams.get("action");
  if (action === "set-password") {
    const uid = urlParams.get("uid");
    const userId = urlParams.get("userId");

    try {
      let user = await window.db.get("users", userId);
      if (!user && window.firebase && window.firebase.firestore) {
        try {
          const snap = await window.firebase.firestore().collection("users").doc(userId).get();
          if (snap.exists) {
            user = snap.data();
            await window.db.putLocal("users", user);
          }
        } catch (cloudErr) {
          console.warn("Direct cloud user lookup notice:", cloudErr);
        }
      }

      if (user && user.uid === uid && (user.status === "ACTIVE" || user.status === "PENDING_PASSWORD")) {
        document.getElementById("set-pwd-uid").value = uid;
        document.getElementById("set-pwd-userid").value = userId;
        document.getElementById("set-pwd-display-name").value = `${formatFullName(user)} (${user.uid})`;
        navigateTo("view-set-password");
        showToast("Set your account password to begin.", "info");
      } else {
        showToast("Invalid or expired password setting link.", "danger");
        navigateTo("view-login");
      }
    } catch (err) {
      console.error("Set password routing failure:", err);
      navigateTo("view-login");
    }
  } else {
    // Automatically restore active session if available
    const savedToken = localStorage.getItem("fja_session_token");
    if (savedToken && window.api) {
      const claims = window.api.decodeToken(savedToken);
      if (claims && claims.user_id) {
        try {
          const freshUser = await window.db.get("users", claims.user_id);
          if (freshUser && freshUser.status === "ACTIVE") {
            currentUser = freshUser;
            window.currentUser = freshUser;
            currentToken = savedToken;
            window.api.setCurrentUser(freshUser);
            await enterDashboardPortal();
            return;
          } else {
            localStorage.removeItem("fja_session_token");
            localStorage.removeItem("fja_session_user");
          }
        } catch (sessionErr) {
          console.warn("Could not restore session from storage:", sessionErr);
          localStorage.removeItem("fja_session_token");
          localStorage.removeItem("fja_session_user");
        }
      }
    }
    navigateTo("view-login");
  }

  // --- Submit handler for form-set-new-password ---
  document.getElementById("form-set-new-password").addEventListener("submit", async (e) => {
    e.preventDefault();
    const submitBtn = e.target.querySelector('button[type="submit"]');
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.dataset.origText = submitBtn.innerHTML;
      submitBtn.innerHTML = "Activating Password...";
    }

    const uid = document.getElementById("set-pwd-uid").value;
    const userId = document.getElementById("set-pwd-userid").value;
    const newPwd = document.getElementById("set-pwd-input").value;
    const confirmPwd = document.getElementById("set-pwd-confirm").value;

    if (newPwd.length < 6) {
      showToast("Password must be at least 6 characters.", "warning");
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = submitBtn.dataset.origText || "Activate & Save Password";
      }
      return;
    }
    if (newPwd !== confirmPwd) {
      showToast("Passwords do not match.", "warning");
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = submitBtn.dataset.origText || "Activate & Save Password";
      }
      return;
    }

    try {
      // Register in Firebase Auth if enabled
      if (window.isFirebaseConfigured && window.isFirebaseConfigured()) {
        try {
          const authEmail = `${uid}@fathersjoy.com`;
          await firebase.auth().createUserWithEmailAndPassword(authEmail, newPwd);
          console.log("Firebase Auth account successfully created.");
        } catch (authErr) {
          if (authErr.code === "auth/email-already-in-use") {
            console.log("User already exists in Firebase Auth. Updating credentials.");
          } else {
            console.error("Firebase auth creation error:", authErr);
          }
        }
      }

      // Update Local IndexedDB
      let user = await window.db.get("users", userId);
      if (!user && window.firebase && window.firebase.firestore) {
        try {
          const snap = await window.firebase.firestore().collection("users").doc(userId).get();
          if (snap.exists) user = snap.data();
        } catch (e) {}
      }

      if (user) {
        user.password_hash = await window.api.hashPassword(newPwd);
        user.is_temporal_pwd = false;
        user.status = "ACTIVE";
        await window.db.put("users", user);

        // Audit Log
        await window.db.put("audit_logs", {
          audit_id: "a-audit-" + Date.now(),
          timestamp: new Date().toISOString(),
          action_details: JSON.stringify({
            action: "SET_PASSWORD",
            uid: uid,
            name: formatFullName(user),
            timestamp: new Date().toISOString()
          })
        });

        showToast("Password successfully activated! Please login.", "success");
        navigateTo("view-login");
      } else {
        showToast("User record not found.", "danger");
      }
    } catch (err) {
      console.error("Password initialization failed:", err);
      showToast("Account activation failed: " + err.message, "danger");
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.innerHTML = submitBtn.dataset.origText || "Activate & Save Password";
      }
    }
  });
});





